-- N-1d (Gary, 2026-11-02; docs/DECISIONS.md, docs/prompts/N-1d_AUDIT.md).
-- Part 1 is generated by `prisma migrate diff`; parts 2 and 3 are
-- hand-authored, because the schema cannot express them.

-- 1. N1D-F1: proof without numbers. A NULL basis = a proof-only record
--    ("No nutrition" everywhere). Relaxes NOT NULL only; nothing is dropped.
-- AlterTable
ALTER TABLE "IngredientNutrition" ALTER COLUMN "basisAmount" DROP NOT NULL,
ALTER COLUMN "basisUnit" DROP NOT NULL;

-- 2. N1D-F1c: "the database check that basis amount and unit are empty
--    together". Every existing row has both, so it holds on creation.
--    HAND-AUTHORED — Prisma neither generates nor drops CHECK constraints
--    (docs/MIGRATIONS.md, re-confirmed 2026-08-12), so a baseline squash
--    would silently omit it (Hazard 1).
ALTER TABLE "IngredientNutrition" ADD CONSTRAINT "IngredientNutrition_basis_together"
  CHECK (("basisAmount" IS NULL) = ("basisUnit" IS NULL));

-- 3. N1D-F2 backfill: "Backfill any Verified record without a document to
--    Estimated." The RESET_TO_ESTIMATED shape (src/lib/nutrition-proof.ts).
--    F2b: no AuditLog row; per-branch counts go in MIGRATIONS.md and
--    DEPLOY_LOG.md.
UPDATE "IngredientNutrition"
SET "status" = 'ESTIMATED', "verifiedAt" = NULL, "verifiedByUserId" = NULL
WHERE "status" = 'VERIFIED' AND "labelFileUrl" IS NULL;
